/* cppi::117b4ba417aabfd9346f25623855253269455b1f44b3dd46b74057ecf90bbf97 */
select distinct ultimate_process  from holdings.ma_holding_lookthrough_extended 
where  business_date = date'2025-06-24' and cppib_sec_id not in ('Error','Not Applicable') and currency_of_exposure_code is null

